mapper.select:
SELECT COALESCE(MAX(display_order), 0)
FROM Watchlist_Items
WHERE watchlist_id = #{watchlistId}

mapper.update:
UPDATE Watchlist_Items
SET display_order = #{displayOrder}
WHERE item_id = #{itemId}

UPDATE Watchlist_Items
SET alert_status = 'TRIGGERED', alert_triggered_at = now(), alert_triggered_price = #{price}
WHERE item_id = #{itemId} AND alert_status = 'ACTIVE' AND alert_armed_at = #{armedAt}

update.foreach:
UPDATE Watchlist_Items
SET display_order = #{displayOrder}
WHERE item_id = #{itemId} AND watchlist_id = #{watchlistId}
